237	  /**
238	   * Validate a list of ranges (including overlapping checks) and
239	   * return the sorted list.
240	   * <p>
241	   * Two ranges overlap when the start offset
242	   * of second is less than the end offset of first.
243	   * End offset is calculated as start offset + length.
244	   * @param input input list
245	   * @param fileLength file length if known
246	   * @return a new sorted list.
247	   * @throws IllegalArgumentException if there are overlapping ranges or
248	   * a range element is invalid (other than with negative offset)
249	   * @throws EOFException if the last range extends beyond the end of the file supplied
250	   *                      or a range offset is negative
251	   */
252	  public static List<? extends FileRange> validateAndSortRanges(
253	      final List<? extends FileRange> input,
254	      final Optional<Long> fileLength) throws EOFException {
255	
256	    requireNonNull(input, "Null input list");
257	    checkArgument(!input.isEmpty(), "Empty input list");
258	    final List<? extends FileRange> sortedRanges;
259	
260	    if (input.size() == 1) {
261	      validateRangeRequest(input.get(0));
262	      sortedRanges = input;
263	    } else {
264	      sortedRanges = sortRanges(input);
265	      FileRange prev = null;
266	      for (final FileRange current : sortedRanges) {
267	        validateRangeRequest(current);
268	        if (prev != null) {
269	          checkArgument(current.getOffset() >= prev.getOffset() + prev.getLength(),
270	              "Overlapping ranges %s and %s", prev, current);
271	        }
272	        prev = current;
273	      }
274	    }
275	    // at this point the final element in the list is the last range
276	    // so make sure it is not beyond the end of the file, if passed in.
277	    // where invalid is when the last range is beyond the end of the file.
278	    if (fileLength.isPresent()) {
279	      final FileRange last = sortedRanges.get(sortedRanges.size() - 1);
280	      final Long l = fileLength.get();
281	      // this check is only done if there is a file length passed in.
282	      if (last.getOffset() + last.getLength() > l) {
283	        throw new EOFException("Range [" + last.getOffset() + ", "
284	            + (last.getOffset() + last.getLength()) + ") extends beyond"
285	            + " the length of the file: " + l);
286	      }
287	    }
288	    return sortedRanges;

